    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    try:
        record = vulnerability_store.remove(raw_id, raw_vulnerability_id)
    except VulnerabilityError as exc:
