def _handle_vulnerability_exception_item(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    raw_exception_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "DELETE":
        return _error(
